// File storage helpers. Stored names are generated by the server - the uploaded filename is
// only kept as display metadata and is never used to build a filesystem path.
const crypto = require("crypto");
const fs = require("fs/promises");
const path = require("path");
const { config } = require("../config");

const SUBDIRS = ["projects", "profile", "resume"];

async function ensureUploadDirs() {
  await Promise.all(SUBDIRS.map((dir) => fs.mkdir(path.join(config.uploadDir, dir), { recursive: true })));
}

// Resolves a relative upload path and refuses anything that would leave the upload folder.
function resolveUploadPath(relativePath) {
  const root = path.resolve(config.uploadDir);
  const absolute = path.resolve(root, relativePath);
  if (absolute !== root && !absolute.startsWith(root + path.sep)) return null;
  return absolute;
}

// Writes a buffer to <uploads>/<subdir>/<unique name><ext>. Returns what must be stored in SQLite.
async function saveBuffer(subdir, buffer, ext) {
  if (!SUBDIRS.includes(subdir)) throw new Error("Unknown upload folder.");
  const storedName = `${Date.now()}-${crypto.randomBytes(12).toString("hex")}${ext}`;
  const filePath = `${subdir}/${storedName}`;
  await fs.writeFile(resolveUploadPath(filePath), buffer, { flag: "wx" });
  return { storedName, filePath };
}

// Best-effort delete: a missing file is fine, and failures are logged instead of crashing a request.
async function removeFile(relativePath) {
  if (!relativePath) return;
  const absolute = resolveUploadPath(relativePath);
  if (!absolute) return;
  try {
    await fs.unlink(absolute);
  } catch (error) {
    if (error.code !== "ENOENT") console.error("Could not delete file:", relativePath, error.code);
  }
}

async function removeFiles(relativePaths) {
  await Promise.all(relativePaths.map((item) => removeFile(item)));
}

module.exports = { ensureUploadDirs, resolveUploadPath, saveBuffer, removeFile, removeFiles };
